/* A WALL, not a paragraph of logos.
 *
 * It used to be `flex-wrap`, which packs the marks from the leading edge and
 * leaves whatever is left over at the end of the last line: four wordmarks in a
 * card came out as a ragged 2x2 block pinned to the left, and read as a list of
 * headings someone had failed to align (owner, 23.08). A wall is a GRID —
 * even cells, each mark centred in its own, however many fit. */
.logo-wall {
  /* Local to this component: the cap on how tall any mark may draw itself, and
   * the narrowest cell a wordmark still reads in. */
  --logo-height: var(--space-8);
  --logo-cell: 8rem;

  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(var(--logo-cell), 1fr));
  place-items: center;
  gap: var(--space-6) var(--space-4);
  margin: 0;
  padding: 0;
  list-style: none;
}
.logo-wall[data-size="sm"] { --logo-height: var(--space-6); --logo-cell: 7rem; gap: var(--space-4); }
.logo-wall[data-size="lg"] { --logo-height: var(--space-12); --logo-cell: 10rem; }

/* The normalisation, and the whole reason this is a component: one height, one
 * weight, one opacity, so a heavy wordmark and a thin one carry the same
 * emphasis. `colour` opts out for the row somebody negotiated. */
.logo-wall img {
  display: block;
  block-size: var(--logo-height);
  inline-size: auto;
  max-inline-size: 100%;
  object-fit: contain;
  filter: grayscale(1);
  opacity: 0.7;
}
.logo-wall[data-colour] img { filter: none; opacity: 1; }

import "./LogoWall.css";
import { cn } from "../lib/cn";

type Size = "sm" | "md" | "lg";

export type Logo = {
  src: string;
  /** The organisation's name. Never empty: the mark IS the information here, so
   *  a reader who cannot see it still has to learn who is on the wall. */
  alt: string;
};

type Props = {
  logos: Logo[];
  /** How much the row carries: `md` when the wall is a section of its own, `sm` under a heading
   *  as supporting evidence.
   */
  size?: Size;
  /** Full colour instead of the normalised weight. For one row of partners the
   *  client insisted on; the default exists because unlike marks at full
   *  strength read as a jumble. */
  colour?: boolean;
  /** What the wall is: "Customers", "Partners". */
  label?: string;
  className?: string;
};

/** Customer or partner marks in ONE optical weight: unlike logos are drawn at
 *  unlike strengths, and a row of them at full colour reads as noise rather
 *  than as proof. Normalising that is systems work — done per page it is done
 *  by eye, and looks it. 
 *
 * Copy: every `alt` is the organisation's name in full. The mark IS the
 * information here, so a reader who cannot see it learns who is on the
 * wall only from that word.
 */
export function LogoWall({ logos, size, colour, label, className }: Props) {
  if (!logos.length) return null;
  return (
    <ul className={cn("logo-wall", className)} data-size={size} data-colour={colour ? "" : undefined} aria-label={label}>
      {logos.map((l) => (
        <li key={l.src}>
          <img src={l.src} alt={l.alt} />
        </li>
      ))}
    </ul>
  );
}
